INSERT INTO `window_target` (`key`, `seq`, `value`, `group_id`, `text`) SELECT `key`, `seq`, `value`, `group_id`, `text` FROM (WITH dh_window_clocked AS (SELECT dh_window_input.*, PROCTIME() AS `__dh_window_clock` FROM (SELECT `key` AS `key`, `seq` AS `seq`, `value` AS `value`, `group_id` AS `group_id`, `text` AS `text` FROM (SELECT `key`, `seq`, `value`, `group_id`, `text` FROM `window_source`) dh_stage) dh_window_input), dh_windowed AS (SELECT * FROM TABLE(TUMBLE(TABLE dh_window_clocked, DESCRIPTOR(`__dh_window_clock`), INTERVAL '2.000' SECOND))) SELECT CAST(`__dh_picked`[1] AS STRING) AS `key`, CAST(`__dh_picked`[2] AS BIGINT) AS `seq`, CAST(`__dh_picked`[3] AS DECIMAL(38,18)) AS `value`, CAST(`__dh_picked`[4] AS BIGINT) AS `group_id`, CAST(`__dh_picked`[5] AS STRING) AS `text` FROM (SELECT DH_WINDOW_PICK(ARRAY[CAST(`key` AS STRING), CAST(`seq` AS STRING), CAST(`value` AS STRING), CAST(`group_id` AS STRING), CAST(`text` AS STRING)], '1|F|1000|1048576|1:A:N|1') AS `__dh_picked` FROM dh_windowed GROUP BY window_start, window_end, LOWER(`key`)) dh_window_result) dh_output;